# PERSONA GENERATION
# ═══════════════════════════════════════════════════════════════

def _branch_fingerprint(br):
    """Deterministic hash of the branch set actually driving the persona
    read (uninumbr + zone + opportunity_score, sorted for stability) — if
    this hasn't changed since the last run, the cached brief is still
    accurate and there's no reason to call Claude again."""
    import hashlib
    parts = sorted(
        f"{b.get('uninumbr')}:{b.get('opportunity_zone')}:{b.get('opportunity_score')}"
        for b in br
    )
    return hashlib.md5("|".join(parts).encode()).hexdigest()


def fetch_or_generate_personas(ik, institution_name, br, data):
    """
    Generate a first-level audience brief for the persona slide — same prompt
    philosophy as the Hub's AudienceFinder Audience Intelligence Brief:
    grounded ONLY in the geographic/demographic data BMAP already has
    (household income, home value/ZHVI trend, population trend, opportunity
    zone/score), no invented behavioral or occupation claims, no web search.

    Cached in persona_runs, keyed by inst_key + a fingerprint of the branch
    set. Re-running the same bank with unchanged underlying data returns the
    SAME brief instead of a freshly-generated (and differently-worded) one —
    same fix pattern as Rate Radar's same-day consistency cache. Only calls
    Claude again if the fingerprint has actually changed (branches added/
    removed, or opportunity scores refreshed).
    """
    fingerprint = _branch_fingerprint(br)
    try:
        cached = supabase("persona_runs",
            f"inst_key=eq.{ik}&branch_fingerprint=eq.{fingerprint}"
            "&select=brief_json&order=run_date.desc&limit=1")
        if cached and cached[0].get("brief_json"):
            print(f"  ✓ Using cached audience brief for {institution_name} (unchanged since last run)")
            return cached[0]["brief_json"]
    except Exception as e:
        print(f"  Cache lookup failed for {institution_name}, generating fresh: {e}")

    brief = _generate_audience_brief(institution_name, br, data)

    try:
        supabase_insert("persona_runs", {
            "inst_key": ik,
            "institution_name": institution_name,
            "run_date": datetime.now().isoformat(),
            "branch_fingerprint": fingerprint,
            "branch_count": len(br),
            "brief_json": brief,
            "status": "auto_generated",
        })
    except Exception as e:
        print(f"  Could not cache audience brief for {institution_name} (non-fatal): {e}")

    return brief


def _enforce_brief_char_limits(brief):
    """
    Hard safety net on top of the prompt's length instructions — the model
    mostly complies but not always exactly, and this slide's boxes are fixed
    size (not a scrolling Hub page), so any overflow visually collides with
    the field below it. Mirrors the FIELD_CHAR_LIMITS pattern already used
    for the narrative headline/spoken/close fields elsewhere in this file.
    """
    LIMITS = {
        "paragraph": 320,
        "asymmetric": 200,
    }
    PERSONA_LIMITS = {
        "name": 30, "descriptor": 55, "life_stage": 22,
        "wealth_signal": 42, "primary_need": 30,
        "switch_driver": 32, "markets": 60,
    }
    BULLET_LIMIT = 155

    for field, limit in LIMITS.items():
        if brief.get(field) and len(brief[field]) > limit:
            brief[field] = truncate_label(brief[field], limit)

    for field in ("strong", "watch"):
        brief[field] = [
            truncate_label(s, BULLET_LIMIT) if len(s) > BULLET_LIMIT else s
            for s in (brief.get(field) or [])
        ]

    for p in brief.get("personas", []) or []:
        for field, limit in PERSONA_LIMITS.items():
            if p.get(field) and len(p[field]) > limit:
                p[field] = truncate_label(p[field], limit)

    return brief


def _generate_audience_brief(institution_name, br, data):
    """Single first-level Claude call — mirrors the Hub's agRenderPersona() prompt."""
    # NOTE: this previously read data.get("rows", []) instead of the br param —
    # "rows" is the bank-level summary row (just namefull/metro), not branch-level
    # data, so every branch came back with income/home-value/population all
    # blank. That's why Claude's response literally said the dataset had no
    # branch names or demographics — it was telling the truth about what it
    # was given. Fixed to use the actual branch-level list.
    target_br = [b for b in br if b.get("opportunity_zone") in ("Invest", "Analyze")
                 and float(b.get("latest_dep") or 0) >= 5e6]
    if not target_br:
        target_br = [b for b in br if float(b.get("latest_dep") or 0) >= 5e6]
    if not target_br:
        target_br = br

    def branch_line(b):
        inc = b.get("household_income")
        zhvi = b.get("zhvi")
        zhvi_yoy = b.get("zhvi_yoy_pct")
        pop = b.get("total_population")
        pop_yoy = b.get("yoy_pop_growth")
        score = b.get("opportunity_score")
        zone = b.get("opportunity_zone", "—")
        return (f"{b.get('namebr','—')} ({b.get('citybr','—')}, {b.get('stalpbr','—')}) — "
                f"income {f'${float(inc)/1000:.0f}k' if inc else '—'}, "
                f"home value {f'${float(zhvi)/1000:.0f}k' if zhvi else '—'}"
                f"{f' ({float(zhvi_yoy):+.1f}% YoY)' if zhvi_yoy else ''}, "
                f"population {f'{float(pop):,.0f}' if pop else '—'}"
                f"{f' ({float(pop_yoy)*100:+.1f}% YoY)' if pop_yoy else ''}, "
                f"zone {zone}, opportunity score {f'{float(score):.0f}/100' if score else '—'}")

    branch_ctx = "\n".join(f"- {branch_line(b)}" for b in target_br)
    context = f"Priority markets for {institution_name}:\n{branch_ctx}"

    fallback = _audience_brief_fallback(institution_name, target_br, reason="no_key")

    if not ANTH_KEY:
        print("  ⚠  No ANTHROPIC_API_KEY — using data-only fallback audience brief")
        return fallback

    system = (
        "You are a first-level audience analyst at Verlocity writing a briefing note for the "
        "team's own use — the same tone and structure as our Financial Intelligence Brief, "
        "applied to audience/persona instead of financials. Given only geographic and "
        "demographic data (household income, home value/ZHVI trend, population trend, BMAP "
        "opportunity zone) for a bank's priority branch markets, write an honest, grounded "
        "read of who these markets are and where the audience opportunity is. This is "
        "explicitly a FIRST-LEVEL geographic/demographic read for the paragraph, strong, and "
        "watch sections — never invent behavioral, psychographic, or purchase-intent claims "
        "there that aren't implied by the numbers given, and say plainly where the read is "
        "limited by data you don't have. "
        "The 'strong' array must only contain claims directly evidenced by the "
        "income/home-value/population/zone/score figures given — never claims about "
        "competitor banks' behavior, underwriting, or product gaps at other institutions, "
        "since that data was not provided; any such speculation belongs in 'watch' instead, "
        "framed as something to validate. "
        "The 'personas' array is the one place you should go a step further than strictly "
        "first-level, the same way our AudienceFinder tool's persona cards do: name 1-2 broad, "
        "named personas — even a single one is fine if the branches don't clearly split into "
        "more. Each persona must be traceable to an actual cluster of branches from the "
        "per-branch breakdown (list them in 'markets'), and every field must follow logically "
        "from that cluster's actual income/home-value/growth numbers — a 'primary_need' of "
        "wealth management only follows if the wealth signal actually shows high income and "
        "high home value; don't invent a need the numbers don't support. "
        "THIS IS A ONE-SLIDE SUMMARY, NOT THE FULL HUB BRIEF — every field below has a HARD "
        "character ceiling because it renders into a fixed-size box on a PowerPoint slide, not "
        "a scrolling web page. If a field runs long, it will visually overlap the field below "
        "it. Write tight and specific — cut qualifying clauses and cite one strongest number "
        "per claim, not three. Treat every limit below as a hard maximum, not a target to "
        "approach — after drafting each field, COUNT its characters and shorten it if it's "
        "even slightly over. Every field must end on a complete clause, never mid-word or "
        "mid-thought — a short complete sentence beats a longer cut-off one every time:\n"
        "Return ONLY a JSON object with keys: paragraph "
        "(string, MAX 300 characters, 2 sentences — the composite audience read: who likely "
        "lives there, income/home-value tier, growth trajectory), "
        "personas (array of 1-2 objects — each field below has its own hard cap: "
        "name MAX 30 characters ('The [Descriptor] [Type]', e.g. 'The Equity Accelerator'); "
        "descriptor MAX 55 characters, one short phrase; "
        "life_stage MAX 22 characters, e.g. '35-55, established'; "
        "wealth_signal MAX 40 characters, the core income/home-value figures only, e.g. "
        "'$53k-$74k, homes +7-10% YoY'; "
        "primary_need MAX 30 characters, e.g. 'Home equity / HELOC'; "
        "switch_driver MAX 32 characters, e.g. 'Faster equity access'; "
        "markets MAX 55 characters, comma-separated branch names only, no descriptions), "
        "strong (array of 3 strings, MAX 150 characters each, format 'Signal — implication', "
        "the clearest audience opportunities visible in the data), "
        "watch (array of 2 strings, MAX 150 characters each, format 'Gap — what to validate', "
        "honest about what this first-level read can't tell you — end on a complete clause, "
        "never a dangling word), "
        "asymmetric (string, MAX 190 characters, 1 sentence — the single most specific, "
        "actionable targeting angle, referencing actual branch "
        "names/markets). No markdown, no preamble, ONLY valid JSON."
    )

    import anthropic
    client = anthropic.Anthropic(api_key=ANTH_KEY)
    try:
        response = client.messages.create(
            model="claude-sonnet-5",
            max_tokens=2000,
            # Sonnet 5 has adaptive thinking ON BY DEFAULT, and thinking tokens
            # count against max_tokens. With a detailed system prompt like this
            # one, the model can spend its entire budget thinking and hit
            # stop_reason="max_tokens" before writing any actual output text —
            # which is exactly what produced the empty "Response: " in the logs.
            # This is a direct structured-JSON task, not multi-step reasoning,
            # so thinking isn't needed here — disable it outright.
            thinking={"type": "disabled"},
            system=system,
            messages=[{"role": "user", "content": context}]
        )
        txt = "".join(b.text for b in response.content if hasattr(b, "text") and b.text)
        clean = txt.replace("```json", "").replace("```", "").strip()
        s = clean.find("{")
        if s >= 0:
            # Parse only the FIRST valid JSON object and ignore anything after
            # it. The previous approach (slicing to the LAST '}' in the whole
            # response) assumed there was exactly one JSON blob — it broke
            # here because the model echoed/duplicated the JSON object, so
            # the last '}' belonged to a second copy, and the slice between
            # them concatenated both into a string with "extra data" after
            # the first complete object. raw_decode stops at the first valid
            # object regardless of what follows.
            try:
                # strict=False lets a stray literal control character (e.g. a
                # raw newline the model left inside a string value instead of
                # keeping the field on one line) through without failing the
                # whole parse — this was the most likely single cause of
                # "Claude responded but the reply wasn't valid JSON" runs,
                # since the model was otherwise following the format correctly.
                brief, _end = json.JSONDecoder(strict=False).raw_decode(clean[s:])
                if brief.get("paragraph"):
                    brief = _enforce_brief_char_limits(brief)
                    print(f"  ✓ Generated audience brief for {institution_name}")
                    return brief
            except json.JSONDecodeError:
                # Second line of defense: ask Claude to repair its own output
                # into strict JSON, once, rather than immediately falling back
                # to the no-narrative slide over a formatting slip.
                try:
                    repair = client.messages.create(
                        model="claude-sonnet-5",
                        max_tokens=2000,
                        thinking={"type": "disabled"},
                        system=("The following is meant to be a JSON object but failed to parse. "
                                "Return ONLY the corrected, strictly valid JSON — same content, "
                                "fixed formatting. No markdown, no preamble."),
                        messages=[{"role": "user", "content": clean[s:]}]
                    )
                    rtxt = "".join(b.text for b in repair.content if hasattr(b, "text") and b.text)
                    rclean = rtxt.replace("```json", "").replace("```", "").strip()
                    rs = rclean.find("{")
                    if rs >= 0:
                        brief, _end = json.JSONDecoder(strict=False).raw_decode(rclean[rs:])
                        if brief.get("paragraph"):
                            brief = _enforce_brief_char_limits(brief)
                            print(f"  ✓ Generated audience brief for {institution_name} (after one repair pass)")
                            return brief
                except Exception as repair_err:
                    print(f"  Repair pass also failed for {institution_name}: {repair_err}")
        # Diagnostic detail so an empty/malformed response is never a dead end
        # again — block types and stop_reason tell you WHY txt came back empty
        # (e.g. stop_reason="max_tokens" with only a thinking block present).
        block_types = [getattr(b, "type", type(b).__name__) for b in response.content]
        print(f"  Could not parse audience brief JSON for {institution_name}. "
              f"stop_reason={response.stop_reason}, blocks={block_types}, "
              f"response text: {txt[:200]!r}")
        return _audience_brief_fallback(institution_name, target_br, reason="parse_failed")
    except Exception as e:
        print(f"  ⚠️⚠️⚠️  Audience brief generation FAILED for {institution_name}: {e}. "
              f"Using data-only fallback — slide will show real numbers but no AI narrative.")
        return _audience_brief_fallback(institution_name, target_br, reason=f"api_error: {e}")


def _audience_brief_fallback(institution_name, target_br, reason="unknown"):
    """
    Data-only fallback when Claude is unavailable or fails — deliberately does NOT
    pretend to be an AI-generated insight. Previously this silently fell back to a
    hardcoded generic persona template that was indistinguishable from real output;
    that's exactly what caused the "always generic" bug. This version is honest
    about being a fallback and only states numbers actually in the data.

    'reason' makes the slide itself diagnostic — previously all three failure paths
    (no key / API error / bad JSON) produced identical text, so there was no way to
    tell which one happened without pulling Railway logs.
    """
    def sf(key):
        vals = [float(v) for b in target_br if (v := b.get(key)) not in (None, "")]
        return sum(vals) / len(vals) if vals else None

    avg_income = sf("household_income")
    avg_zhvi = sf("zhvi")
    avg_zhvi_yoy = sf("zhvi_yoy_pct")
    n = len(target_br)

    if reason == "no_key":
        reason_text = "the ANTHROPIC_API_KEY environment variable is not set for this service"
    elif reason == "parse_failed":
        reason_text = "Claude responded but the reply wasn't valid JSON (check Railway logs for the raw response)"
    elif reason.startswith("api_error:"):
        reason_text = f"the Claude API call failed ({reason[len('api_error: '):][:120]})"
    else:
        reason_text = "of an unknown error — check Railway logs"

    paragraph = (
        f"AI-generated audience narrative unavailable for this run because {reason_text}. "
        f"What we can show from the data directly: "
        f"{n} priority branch{'es' if n != 1 else ''}"
        f"{f', averaging ${avg_income/1000:.0f}k household income' if avg_income else ''}"
        f"{f' and ${avg_zhvi/1000:.0f}k home values' if avg_zhvi else ''}"
        f"{f' ({avg_zhvi_yoy:+.1f}% YoY)' if avg_zhvi_yoy else ''}."
    )
    return {
        "paragraph": paragraph,
        "personas": [],
        "strong": [],
        "watch": ["AI narrative generation did not run for this deck — this section is data-only."],
        "asymmetric": "",
    }




def add_rect(slide, x, y, w, h, fill_color, line_color=None, line_width=Pt(0)):
    shape = slide.shapes.add_shape(1, Inches(x), Inches(y), Inches(w), Inches(h))
    shape.fill.solid(); shape.fill.fore_color.rgb = fill_color
    if line_color:
        shape.line.color.rgb = line_color
        shape.line.width = line_width
    else:
        shape.line.fill.background()
    return shape

def add_text(slide, text, x, y, w, h, size=11, bold=False, color=NAVY,
             align=PP_ALIGN.LEFT, italic=False, font="Inter", valign="top",
             shrink_to_fit=False):
    tb = slide.shapes.add_textbox(Inches(x), Inches(y), Inches(w), Inches(h))
    tf = tb.text_frame
    tf.word_wrap = True
    if shrink_to_fit:
        from pptx.enum.text import MSO_AUTO_SIZE
        tf.auto_size = MSO_AUTO_SIZE.TEXT_TO_FIT_SHAPE
    from pptx.enum.text import MSO_ANCHOR
    tf.vertical_anchor = {"top": MSO_ANCHOR.TOP, "bottom": MSO_ANCHOR.BOTTOM,
                           "center": MSO_ANCHOR.MIDDLE}.get(valign, MSO_ANCHOR.TOP)
    p = tf.paragraphs[0]
    p.alignment = align
    run = p.add_run()
    run.text = str(text)
    run.font.name = font
    run.font.size = Pt(size)
    run.font.bold = bold
    run.font.italic = italic
    run.font.color.rgb = color
    return tb

def _why_vulnerable(c):
    """Turns the raw signals behind a vulnerability score into a short,
    specific reason — 'because of what' rather than just the number.
    Priority order matches the size of each factor's weight in the
    underlying formula (declining deposits and weak ROA carry the most
    weight; proximity and credit quality are secondary)."""
    reasons = []
    yoy = c.get("target_yoy_pct")
    roa = c.get("target_roa")
    noncur = c.get("target_noncurrent_pct")
    dist = c.get("target_dist_mi")
    if yoy is not None and float(yoy) < 0:
        reasons.append(f"deposits down {float(yoy):.1f}% YoY")
    if roa is not None and float(roa) < 0.5:
        reasons.append(f"weak ROA ({float(roa):.2f}%)")
    if noncur is not None and float(noncur) > 2:
        reasons.append(f"rising noncurrent assets ({float(noncur):.1f}%)")
    if dist is not None and float(dist) <= 1:
        reasons.append("directly adjacent, <1 mi away")
    if not reasons:
        return "Elevated exposure across several signals, no single dominant factor"
    return "Standout signal: " + " and ".join(reasons[:2])


def _sales_narrative(c):
    """Same underlying signals as _why_vulnerable, but written to sell the
    opportunity rather than report the data — this feeds the peer cards on
    the Competitive Overview slide specifically, which exist to hook a
    first-time prospect, not to document a methodology."""
    dist = c.get("target_dist_mi")
    yoy = c.get("target_yoy_pct")
    roa = c.get("target_roa")
    noncur = c.get("target_noncurrent_pct")

    if dist is not None and float(dist) < 1:
        loc = "sitting directly in your trade area"
    elif dist is not None and float(dist) < 5:
        loc = f"just {float(dist):.1f} miles from your nearest branch"
    elif dist is not None:
        loc = f"within {float(dist):.1f} miles of your footprint"
    else:
        loc = "within your market"

    signals = []
    if yoy is not None and float(yoy) < 0:
        signals.append(f"losing deposits at {abs(float(yoy)):.1f}% a year")
    if roa is not None and float(roa) < 0.5:
        signals.append("running on thin profitability")
    if noncur is not None and float(noncur) > 2:
        signals.append("carrying rising credit-quality strain")

    if signals:
        signal_clause = " and ".join(signals[:2])
        return (f"{loc[0].upper()}{loc[1:]} — and {signal_clause}. Their customers are "
                f"the ones most likely already looking for a better banking relationship.")
    return f"{loc[0].upper()}{loc[1:]} — a real head-to-head opportunity worth watching closely."


def truncate_label(text, max_len):
    """Truncate to max_len, breaking on the last word boundary rather than mid-word."""
    if len(text) <= max_len:
        return text
    cut = text[:max_len]
    if " " in cut:
        cut = cut[:cut.rindex(" ")]
    return cut.rstrip() + "…"

